-- Exact aggregates in one snapshot; do not download wallet/password documents for dashboard totals.
create or replace function inex_private.as_numeric(value text) returns numeric language sql immutable security invoker set search_path='' as $$select case when value ~ '^-?[0-9]+(\.[0-9]+)?([eE][+-]?[0-9]+)?$' then value::numeric else 0 end;$$;
create or replace function inex_private.as_timestamp(value jsonb) returns timestamptz language plpgsql stable security invoker set search_path='' as $$begin if jsonb_typeof(value)='number' then return to_timestamp((value#>>'{}')::double precision/1000);end if;return (value#>>'{}')::timestamptz;exception when others then return null;end;$$;
revoke all on function inex_private.as_numeric(text),inex_private.as_timestamp(jsonb) from public,anon,authenticated;
grant execute on function inex_private.as_numeric(text),inex_private.as_timestamp(jsonb) to service_role;
create or replace function public.inex_admin_metrics(p_now timestamptz default now(),p_timezone text default 'America/Sao_Paulo') returns jsonb language sql stable security invoker set search_path='' as $$
with base as materialized(select collection_id,document_id,data from public.inex_documents where not deleted and collection_id in('users','transactions','affiliates','gameBets','gameConfigs')),
u as materialized(select document_id,data,inex_private.as_numeric(data->>'balance') balance,inex_private.as_timestamp(data->'createdAt') at from base where collection_id='users'),
t as materialized(select document_id,data,inex_private.as_numeric(data->>'amount') amount,inex_private.as_timestamp(data->'createdAt') at,case when lower(coalesce(data->>'paymentMethod','')) ~ 'gendino|blockwin|bubbleblast|subwaypay|raspafortuna|countmasters|gameprize|afiliados|admin|manual|ajuste|demo|influenciador' or lower(coalesce(data->>'description','')) ~ 'vitória gen dino|lucro do jogo|lucro blockwin|partida|prêmio de jogo|admin|manual|ajuste|demo|influenciador' then false else true end cash from base where collection_id='transactions'),
a as(select coalesce(sum(inex_private.as_numeric(data->>'affiliateBalance')),0) balance,coalesce(sum(inex_private.as_numeric(data->>'commissionTotal')),0) commission from base where collection_id='affiliates'),
b as(select coalesce(sum(inex_private.as_numeric(data->>'betAmount')),0) wagered,coalesce(sum(inex_private.as_numeric(data->>'payoutAmount')),0) payout from base where collection_id='gameBets' and data->>'status' is distinct from 'active'),
g as(select count(*) total,count(*) filter(where data->>'status'='active' and not coalesce((data->>'maintenance')::boolean,false)) active from base where collection_id='gameConfigs' and document_id in('g_gen_dino','g_block_puzzle','g_zumbla','g_raspa_fortuna','g_subway_pay','g_bubble_blast','g_count_masters')),
clock as(select date_trunc('day',p_now at time zone p_timezone) today),
valid as materialized(select *,data->>'type' kind from t where cash and data->>'status'='approved' and data->>'type' in('deposit','withdrawal')),
days as(select to_char(at at time zone p_timezone,'YYYY-MM-DD') as "day",coalesce(sum(amount) filter(where kind='deposit'),0) deposits,count(*) filter(where kind='deposit') deposit_count,coalesce(sum(amount) filter(where kind='withdrawal'),0) withdrawals,count(*) filter(where kind='withdrawal') withdrawal_count from valid,clock where at >= ((clock.today-interval '29 days') at time zone p_timezone) group by "day"),
hours as(select floor(extract(hour from at at time zone p_timezone)/3)::integer*3 as "hour",coalesce(sum(amount) filter(where kind='deposit'),0) deposits,count(*) filter(where kind='deposit') deposit_count,coalesce(sum(amount) filter(where kind='withdrawal'),0) withdrawals,count(*) filter(where kind='withdrawal') withdrawal_count from valid,clock where at >= (clock.today at time zone p_timezone) and at <((clock.today+interval '1 day') at time zone p_timezone) group by "hour"),
activities as((select t.document_id id,t.data->>'type' type,case when t.data->>'type'='deposit' then case when t.data->>'status'='approved' then 'Depósito aprovado' else 'Depósito em processamento' end else case when t.data->>'status'='approved' then 'Saque PIX processado' else 'Saque PIX solicitado' end end title,coalesce(u.data->>'name','Usuário') "userName",t.amount,t.at from t left join u on u.document_id=t.data->>'userId' where t.cash order by t.at desc nulls last limit 10) union all (select 'u_'||document_id,'user_registered','Novo usuário cadastrado',coalesce(data->>'name','Usuário'),null,at from u order by at desc nulls last limit 10))
select jsonb_build_object('observedAt',p_now,'today',(select to_char(today,'YYYY-MM-DD') from clock),'totals',jsonb_build_object(
 'totalUsers',(select count(*) from u),'totalBalance',(select coalesce(sum(balance),0) from u),'totalReferredUsers',(select count(*) from u where coalesce(data->>'affiliateId','')<>''),'newUsersToday',(select count(*) from u,clock where at >= (clock.today at time zone p_timezone)),
 'totalDepositsAmount',(select coalesce(sum(amount),0) from valid where kind='deposit'),'totalDepositsCount',(select count(*) from valid where kind='deposit'),'approvedWithdrawalsAmount',(select coalesce(sum(amount),0) from valid where kind='withdrawal'),
 'pendingWithdrawalsCount',(select count(*) from t where cash and data->>'type'='withdrawal' and data->>'status'='pending'),'pendingWithdrawalsAmount',(select coalesce(sum(amount),0) from t where cash and data->>'type'='withdrawal' and data->>'status'='pending'),
 'totalAffiliateBalance',a.balance,'totalAffiliateCommissionsPaid',a.commission,'totalWagered',b.wagered,'totalPayout',b.payout,'totalGamesCount',g.total,'activeGamesCount',g.active),
 'daily',(select coalesce(jsonb_agg(to_jsonb(days)),'[]') from days),'hourly',(select coalesce(jsonb_agg(to_jsonb(hours)),'[]') from hours),
 'yesterdaySales',(select coalesce(sum(amount),0) from valid,clock where kind='deposit' and at >= ((clock.today-interval '1 day') at time zone p_timezone) and at <(clock.today at time zone p_timezone)),
 'activities',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'type',type,'title',title,'userName',"userName",'amount',amount,'createdAt',extract(epoch from at)*1000) order by at desc),'[]') from(select * from activities where at is not null order by at desc limit 6)recent)) from a,b,g;
$$;
revoke all on function public.inex_admin_metrics(timestamptz,text) from public,anon,authenticated;
grant execute on function public.inex_admin_metrics(timestamptz,text) to service_role;
notify pgrst,'reload schema';
